import {DEMO_SESSIONS} from './fixtures.js';
import {getLanguage,setLanguage,translate,localizeDom,localizePageChrome,languageButton} from './i18n.js';
import {createService,SCENARIOS} from './service.js';
import {METRICS,STATUS,DEFAULT_RULES,triage,displayMetric,isFresh,usable,lcdFrames} from './rules.js';
const service=createService();
const state={patients:[],selected:'p001',filter:'all',query:'',view:'cards',drawer:false,role:'pro',live:true,tab:'overview',chart:'hr',seen:new Set(),lcdIndex:0,lcdAuto:true,history:[],loginError:'',error:'',lastRefresh:Date.now()};
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clock=(t=Date.now(),seconds=true)=>new Intl.DateTimeFormat(getLanguage()==='en'?'en-GB':'zh-CN',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit',...(seconds?{second:'2-digit'}:{})}).format(new Date(t));
const icons={heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',pulse:'M2 12h5l3-8 4 16 3-8h5',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',list:'M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01',alert:'M12 3 2 21h20L12 3Zm0 6v5m0 3h.01',check:'m5 12 4 4L19 6',drop:'M12 3C10 6 5 11 5 15a7 7 0 0 0 14 0c0-4-5-9-7-12Z',temp:'M9 14.8V5a3 3 0 0 1 6 0v9.8a5 5 0 1 1-6 0Zm3-7v10',fall:'M13 4h.01M10 8l4 3 5-2M14 11l-5 4-5-2M9 15l3 6M14 11l3 5 4 1',chevron:'m9 5 7 7-7 7',back:'m15 5-7 7 7 7',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z',refresh:'M20 7V3l-4 4a8 8 0 1 0 3 10M20 3h-5',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM9 3h6l1 4 4 1v6l-4 2-1 5H9l-1-5-5-2V8l5-1 1-4Z',user:'M20 21v-2a7 7 0 0 0-14 0v2M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',users:'M16 21v-2a5 5 0 0 0-10 0v2M15 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM20 21v-2a5 5 0 0 0-3-4M18 3a4 4 0 0 1 0 8',device:'M4 3h16v15H4zM8 22h8M12 18v4',logout:'M9 3H3v18h6M14 8l5 4-5 4M8 12h11',download:'M12 3v12m-5-5 5 5 5-5M3 17v4h18v-4',wifi:'M2 8a16 16 0 0 1 20 0M5 12a11 11 0 0 1 14 0M8 16a6 6 0 0 1 8 0M12 20h.01','wifi-off':'m2 2 20 20M8 4a16 16 0 0 1 14 4M2 8a16 16 0 0 1 3-2M5 12a11 11 0 0 1 5-2M8 16a6 6 0 0 1 8 0M12 20h.01',close:'m6 6 12 12M6 18 18 6',play:'m8 4 13 8-13 8V4Z',pause:'M8 4v16M16 4v16',shield:'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6l-9-4Z',code:'m8 6-6 6 6 6m8-12 6 6-6 6M14 3l-4 18',info:'M12 11v6m0-10h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',sun:'M12 3v2m0 14v2M3 12h2m14 0h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.pulse}"/></svg>`;
const logo=()=>`<a href="#/pro" class="logo"><span class="logo-mark">${icon('pulse')}</span><span>安护<span class="logo-en">CareLink</span></span></a>`;
const status=(p)=>triage(p.reading,service.rules);
const badge=(level,label)=>`<span class="badge ${level}"><span class="dot"></span>${esc(label||STATUS[level].label)}</span>`;
const avatar=(p,size='')=>`<span class="avatar ${p.color} ${size}" aria-label="${esc(p.name)}的虚构头像"><span>${esc(p.name.slice(0,1))}</span></span>`;
const route=()=>location.hash.slice(1)||'/login';
const navigate=p=>{location.hash=p;};
function toast(s){$('#toast').textContent=translate(s);$('#toast').classList.add('show');clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000);}
const visibleDemoPatients=()=>route()==='/family'?state.patients.filter(p=>DEMO_SESSIONS.basic.patientIds.includes(p.id)):state.patients;
const patient=()=>visibleDemoPatients().find(p=>p.id===state.selected)||visibleDemoPatients()[0];
const footnote=()=>`<footer class="page-footer"><span>安护 CareLink <span class="footer-dot">·</span> 课程项目演示 v1.0</span><span>所有人物与读数均为虚构 · 规则仅用于演示交互</span></footer>`;
function shell(content,active='pro'){
 const counts=state.patients.filter(p=>['red','yellow'].includes(status(p).level)).length;
 return `<div class="app-shell"><aside class="sidebar">${logo()}<div class="workspace"><span class="workspace-icon">${icon('shield')}</span><span>安心照护中心<small>演示工作空间</small></span><span class="tiny">⌄</span></div><div class="nav-label">工作台</div><nav aria-label="主要导航"><a class="nav-item ${active==='pro'?'active':''}" href="#/pro">${icon('grid')}<span>患者总览</span></a><a class="nav-item ${active==='alerts'?'active':''}" href="#/alerts">${icon('alert')}<span>关注与警报</span><span class="nav-count">${counts}</span></a><a class="nav-item ${active==='lcd'?'active':''}" href="#/lcd">${icon('device')}<span>设备小屏</span></a><a class="nav-item ${active==='settings'?'active':''}" href="#/settings">${icon('settings')}<span>演示规则</span></a></nav><div class="sidebar-bottom"><div class="demo-side"><span class="demo-label">${icon('code')} DEMO MODE</span><p>先体验，再一起完善。</p><button class="text-btn" data-action="drawer">切换演示场景 ${icon('chevron')}</button></div><div class="account"><span class="avatar mini mint">演</span><span>演示医护人员<small>Pro 工作台</small></span><a href="#/login" class="icon-btn" aria-label="退出演示">${icon('logout')}</a></div></div></aside><div class="main-wrap"><header class="topbar"><span class="breadcrumb">安心照护中心 <span>/</span> ${active==='pro'?'患者监测':active==='alerts'?'关注与警报':active==='lcd'?'设备小屏':'演示规则'}</span><div class="top-actions">${languageButton()}<span class="demo-pill">虚构数据</span><div class="role-switch"><a href="#/pro" class="${active!=='family'?'selected':''}">Pro 医护端</a><a href="#/family">Basic 家属端</a></div><button class="icon-btn" data-action="drawer" aria-label="打开演示控制台">${icon('settings')}</button></div></header><main id="main" tabindex="-1" class="main">${state.error?`<div class="notice red">${esc(state.error)} <button data-action="refresh" class="text-btn">重试</button></div>`:''}${content}${footnote()}</main></div></div>`;
}
function login(){return `<main class="login-page" id="main"><section class="login-story">${logo()}<div class="story-copy"><div class="eyebrow">CARE THAT STAYS CONNECTED</div><h1>每一次关注，<br>都让安心更近一步。</h1><p>连接每一份健康数据，<br>让专业照护与家人的牵挂，时刻相伴。</p></div><div class="care-art" aria-hidden="true"><div class="orbit o1"></div><div class="orbit o2"></div><div class="art-heart">${icon('heart')}</div><div class="floating-card float-left"><span class="round-icon mint">${icon('shield')}</span><span>安心守护<small>跌倒与日常状态监测</small></span><span class="dot green"></span></div><div class="floating-card float-right"><span class="round-icon rose">${icon('pulse')}</span><span>心率 <strong>76 <small>bpm</small></strong></span><svg viewBox="0 0 100 40"><path d="M0 20h20l8-14 12 30 12-21 8 5h40" fill="none" stroke="#258779" stroke-width="2"/></svg></div><span class="art-tag">模拟数据 · 仅作界面展示</span></div><div class="story-bottom">${icon('shield')} 专业视角，温暖连接 <span>CareLink / 01</span></div></section><section class="login-form-wrap"><div class="login-top"><span>Web · Pro / Basic</span>${languageButton()}<span class="version">DEMO v1.0</span></div><div class="login-form"><span class="eyebrow">欢迎来到安护</span><h2>把关心，连接起来</h2><p class="muted">选择你的视角，开始体验健康监测工作台。</p><div class="login-roles" role="group" aria-label="选择演示身份"><button class="role-card ${state.role==='pro'?'selected':''}" data-role="pro">${icon('users')}<strong>Pro 医护人员</strong><small>多患者 · 详细数据</small></button><button class="role-card ${state.role==='family'?'selected':''}" data-role="family">${icon('heart')}<strong>Basic 患者 / 家属</strong><small>简单直观 · 安心查看</small></button></div><form id="login-form"><label>演示账号<input type="email" name="email" value="demo@carelink.example" required autocomplete="off"></label><label>演示密码<input type="password" name="password" value="carelink-demo" required autocomplete="off"></label><p class="form-hint">固定演示表单，不验证身份。请勿输入真实账号或密码。</p><button class="btn primary full" type="submit">进入${state.role==='pro'?'医护工作台':'家属端'} ${icon('chevron')}</button></form><div class="login-note">${icon('info')}<span>所有档案、读数均为虚构；未连接设备或 AI。<br>当前登录仅演示流程，正式使用需接入身份验证。</span></div></div><div class="login-bottom">小组课程项目 <span>用设计，照顾每一种需要。</span></div></section></main>`;}
function summary(){const c={red:0,yellow:0,green:0,unknown:0};state.patients.forEach(p=>c[status(p).level]++);return `<div class="summary-grid">${[['red','优先查看','fall','跌倒或严重数值异常'],['yellow','需要关注','pulse','轻度异常 · 无跌倒事件'],['green','数据平稳','shield','未见演示异常']].map(([k,label,i,desc])=>`<button class="summary-card ${k}" data-filter="${k}"><span class="round-icon ${k}">${icon(i)}</span><span class="summary-info">${label}<strong>${c[k]}<small>位</small></strong><span>${desc}</span></span><span class="summary-arrow">↗</span></button>`).join('')}</div><div class="priority-strip"><span class="round-icon red">${icon('alert')}</span><span><strong>${c.red?`${c.red} 位患者需要优先查看`:'当前没有优先警报'}</strong><small>${c.red?'请核实跌倒事件或异常读数，演示数据不代表真实健康状况。':'持续关注数据质量，缺失数据不判为平稳。'}</small></span><button class="text-btn" data-filter="red">查看警报 ${icon('chevron')}</button></div>`;}
function metricSmall(p,key){const m=displayMetric(p.reading,key,service.rules);return `<div class="mini-metric"><span>${icon(METRICS[key].icon)} ${METRICS[key].name}</span><div class="metric-value ${m.level==='red'?'red-text':m.level==='yellow'?'yellow-text':''}">${m.text}<small>${METRICS[key].unit}</small></div></div>`;}
function patientCard(p){const t=status(p);const fresh=isFresh(p.reading,service.rules);return `<a class="patient-card ${t.level}" href="#/patient/${p.id}" aria-label="查看${esc(p.name)}详情，${STATUS[t.level].label}"><div class="patient-head">${avatar(p)}<div class="patient-name"><h3>${esc(p.name)}</h3><span>${p.sex} · ${p.age} 岁 <i>｜</i> ${p.bed} 床</span></div>${icon('chevron','card-chevron')}</div><div class="patient-status">${badge(t.level)}${t.incomplete&&t.level!=='unknown'?'<span class="tiny">部分数据待确认</span>':''}</div><div class="card-metrics">${Object.keys(METRICS).map(k=>metricSmall(p,k)).join('')}</div><div class="card-event ${t.level}">${icon(t.level==='green'?'check':t.level==='unknown'?'wifi-off':'alert')}<span>${esc(t.level==='green'?'未检测到跌倒事件':t.reasons[0])}</span></div><div class="card-bottom"><span><span class="dot ${fresh?'green':'unknown'}"></span>${p.reading?`${fresh?'模拟更新':'最后采集'} ${clock(p.reading.measuredAt)}`:'等待数据'}</span><span>查看详情 ${icon('chevron')}</span></div></a>`;}
function patientTable(list){return `<div class="table-wrap patient-list"><table><thead><tr><th>患者</th><th>床位</th><th>状态</th><th>心率 bpm</th><th>温度 °C</th><th>详情</th></tr></thead><tbody>${list.map(p=>`<tr><td><a href="#/patient/${p.id}" class="table-person">${avatar(p,'mini')}${esc(p.name)}<small>${p.age} 岁</small></a></td><td>${p.bed}</td><td>${badge(status(p).level)}</td>${['hr','temp'].map(k=>`<td>${displayMetric(p.reading,k,service.rules).text}</td>`).join('')}<td><a class="text-btn" href="#/patient/${p.id}">查看 ${icon('chevron')}</a></td></tr>`).join('')}</tbody></table></div>`;}
function filtered(){const rank={red:0,yellow:1,unknown:2,green:3};return state.patients.filter(p=>(state.filter==='all'||status(p).level===state.filter)&&`${p.name}${translate(p.name,"en")}${p.bed}${p.id}`.toLowerCase().includes(state.query.toLowerCase())).sort((a,b)=>rank[status(a).level]-rank[status(b).level]);}
function patientResults(){const list=filtered();return list.length?(state.view==='cards'?`<div class="patient-grid">${list.map(patientCard).join('')}</div>`:patientTable(list)):`<div class="empty">${icon('search')}<h3>没有找到匹配的患者</h3><p>试试其他姓名、床位，或清除筛选。</p><button class="btn" data-action="clear">清除筛选</button></div>`;}
function dashboard(){const unknown=state.patients.filter(p=>status(p).level==='unknown').length;return shell(`<div class="page-heading"><div><div class="eyebrow">PATIENT MONITORING</div><h1>患者总览<span class="heading-count">${state.patients.length} 位</span></h1><p>每一份数据背后，都有一位需要被关心的人。</p></div><div class="heading-actions"><span class="live-label"><span class="dot ${state.live?'green':'unknown'}"></span>${state.live?'模拟更新 · 每 5 秒':'模拟更新已暂停'}</span><button class="btn" data-action="refresh">${icon('refresh')}刷新数据</button></div></div>${summary()}<section class="patient-section"><div class="section-title"><h2>全部患者 <small>按关注优先级排序</small></h2><span class="muted tiny">${unknown} 位数据待确认</span></div><div class="toolbar"><label class="search-box">${icon('search')}<input id="patient-search" placeholder="搜索姓名、床位或编号" value="${esc(state.query)}" aria-label="搜索患者"></label><div class="filter-tabs" aria-label="按状态筛选">${[['all','全部'],['red','优先'],['yellow','关注'],['green','平稳'],['unknown','待确认']].map(([k,n])=>`<button class="${state.filter===k?'selected':''}" data-filter="${k}" aria-pressed="${state.filter===k}">${n}</button>`).join('')}</div><div class="view-toggle"><button class="icon-btn ${state.view==='cards'?'selected':''}" data-view="cards" aria-label="卡片视图" aria-pressed="${state.view==='cards'}">${icon('grid')}</button><button class="icon-btn ${state.view==='table'?'selected':''}" data-view="table" aria-label="列表视图" aria-pressed="${state.view==='table'}">${icon('list')}</button></div></div><div id="patient-results">${patientResults()}</div></section>`);}
function detailMetric(p,key){const m=displayMetric(p.reading,key,service.rules);return `<div class="detail-metric"><div class="metric-label">${icon(METRICS[key].icon)}${METRICS[key].name}<span class="quality ${m.level}">${m.level==='unknown'?esc(m.note):'模拟数据'}</span></div><strong class="${m.level}-text">${m.text}<small>${METRICS[key].unit}</small></strong><span>${METRICS[key].sensor}</span></div>`;}
function fallMetric(p){const t=isFresh(p.reading,service.rules)&&p.reading.fall.quality==='good';const active=p.reading?.fall?.active;return `<div class="detail-metric"><div class="metric-label">${icon('fall')}跌倒监测</div><strong class="fall-value ${active?'red-text':''}">${active?'检测到跌倒':t?'未检测到':'暂不可用'}</strong><span>MPU6050${active?' · 待人工核实':''}</span></div>`;}
function chart(p){const key=state.chart;const history=[...state.history].reverse();const pts=history.map((r,i)=>({i,value:isFresh(p.reading,service.rules)&&r.connected&&r.scenario!=='stale'&&usable(r.metrics[key])?r.metrics[key].value:null}));const values=pts.filter(p=>p.value!==null).map(p=>p.value);const center=key==='hr'?80:36.5;const min=values.length?Math.min(...values)- (key==='temp'?.5:3):center-5;const max=values.length?Math.max(...values)+(key==='temp'?.5:3):center+5;const y=v=>165-(v-min)/(max-min)*130;const x=i=>48+i*(680/Math.max(1,pts.length-1));let paths=[],current=[];pts.forEach(p=>{if(p.value===null){if(current.length)paths.push(current);current=[];}else current.push(`${x(p.i)},${y(p.value)}`);});if(current.length)paths.push(current);return `<section class="panel chart-panel"><div class="panel-heading"><div><h2>最近 10 分钟趋势</h2><p>每 30 秒一条模拟记录 · 无效读数不连线</p></div><div class="filter-tabs">${Object.entries(METRICS).map(([k,m])=>`<button class="${state.chart===k?'selected':''}" data-chart="${k}">${m.name}</button>`).join('')}</div></div>${values.length?`<svg class="trend-chart" viewBox="0 0 760 205" role="img" aria-label="${METRICS[key].name}最近十分钟模拟趋势，最低 ${Math.min(...values).toFixed(1)}，最高 ${Math.max(...values).toFixed(1)} ${METRICS[key].unit}">${[0,1,2,3].map(i=>`<line x1="48" x2="728" y1="${35+i*43.33}" y2="${35+i*43.33}" stroke="#e7eeeb" stroke-dasharray="4 4"/><text x="1" y="${39+i*43.33}" font-size="11" fill="#83938e">${(max-(max-min)*i/3).toFixed(key==='temp'?1:0)}</text>`).join('')}${paths.map(a=>`<polyline points="${a.join(' ')}" fill="none" stroke="#208779" stroke-width="2.6" stroke-linejoin="round"/>`).join('')}${pts.filter(p=>p.value!==null).map(p=>`<circle cx="${x(p.i)}" cy="${y(p.value)}" r="2.6" fill="#208779"/>`).join('')}${history.length?[0,Math.floor((history.length-1)/2),history.length-1].map(i=>`<text x="${x(i)}" y="197" text-anchor="middle" font-size="11" fill="#83938e">${clock(history[i].measuredAt,false)}</text>`).join(''):''}</svg>`:'<div class="chart-empty">当前没有可用的趋势数据<br><small>请检查设备连接与数据质量</small></div>'}</section>`;}
function historyTable(p){return `<section class="panel history-panel"><div class="panel-heading"><div><h2>最近 10 分钟数据</h2><p>${state.history.length} 条模拟采样 · 上海时间 UTC+8 · 最新在前</p></div><button class="btn" data-action="export">${icon('download')}导出 CSV</button></div><div class="table-wrap history-table"><table><thead><tr><th>采集时间</th><th>心率 bpm</th><th>表面温度 °C</th><th>跌倒事件</th><th>数据质量 / 时效</th></tr></thead><tbody>${state.history.map(r=>`<tr><td>${clock(r.measuredAt)}</td>${['hr','temp'].map(k=>`<td>${r.connected&&usable(r.metrics[k])?(k==='temp'?r.metrics[k].value.toFixed(1):r.metrics[k].value):'—'}</td>`).join('')}<td>${r.fall.active?'<span class="red-text">待核实</span>':'无事件'}</td><td><span class="table-quality">${!r.connected?'设备离线（历史）':r.scenario==='stale'?'过期采集记录':['hr','temp'].some(k=>!usable(r.metrics[k]))?'部分信号无效':'有效历史采样'}</span></td></tr>`).join('')||'<tr><td colspan="5" class="empty">尚无历史数据</td></tr>'}</tbody></table></div><div class="table-note">历史记录按采集时间展示；历史数值不代表当前状态。</div></section>`;}
function rawPanel(p){return `<div class="raw-grid"><section class="panel"><div class="panel-heading"><div><h2>原始传感器数据</h2><p>${p.reading?'模拟快照 · '+clock(p.reading.measuredAt):'等待读数'} · 未做临床解释</p></div>${badge(isFresh(p.reading,service.rules)?'green':'unknown',isFresh(p.reading,service.rules)?'模拟快照':'离线 / 过期快照')}</div><pre>${esc(JSON.stringify(p.reading?.raw||null,null,2))}</pre><p class="panel-note">加速度 m/s² · 角速度 °/s · 红光/红外为模拟原始计数。</p></section><section class="panel"><div class="panel-heading"><div><h2>AI 预测</h2><p>接口占位，未运行预测模型</p></div><span class="tag">待接入</span></div><div class="ai-placeholder">${icon('pulse')}<h3>等待组员提供模型输出</h3><p>结果、置信度、模型版本及预测时间<br>接入后在此显示。</p><span class="badge unknown">当前没有 AI 结论</span></div><pre>${esc(JSON.stringify(p.reading?.ai||{state:'not_connected'},null,2))}</pre></section></div>`;}
function detail(p){if(!p)return shell('<div class="empty"><h1>未找到患者</h1><a href="#/pro">返回总览</a></div>');const t=status(p);return shell(`<a href="#/pro" class="back-link">${icon('back')}返回患者总览</a><div class="detail-header"><div class="detail-person">${avatar(p,'large')}<div><div class="inline"><h1>${esc(p.name)}</h1>${badge(t.level)}</div><p>${p.sex} · ${p.age} 岁 <i>｜</i> ${p.bed} 床 <i>｜</i> 虚构档案 ${p.id.toUpperCase()}</p></div></div><button class="btn" data-action="refresh">${icon('refresh')}刷新数据</button></div><div class="detail-alert ${t.level}">${icon(STATUS[t.level].icon)}<span><strong>${STATUS[t.level].label}</strong> ${esc(t.reasons.join('；'))}</span><small>仅按演示规则计算</small></div><div class="detail-metrics">${['hr','temp'].map(k=>detailMetric(p,k)).join('')}${fallMetric(p)}</div><div class="detail-tabs" role="group" aria-label="详情内容">${[['overview','监测概览'],['history','历史记录'],['raw','原始数据与 AI']].map(([k,n])=>`<button data-tab="${k}" class="${state.tab===k?'active':''}">${n}</button>`).join('')}<span>最后采集：${p.reading?clock(p.reading.measuredAt):'尚无数据'} · ${p.reading?.deviceId||'设备待关联'}</span></div>${state.tab==='raw'?rawPanel(p):state.tab==='history'?historyTable(p):`<div class="detail-content">${chart(p)}<section class="panel profile-panel"><h2>个人档案</h2><dl><div><dt>姓名 / 年龄</dt><dd>${esc(p.name)} / ${p.age} 岁</dd></div><div><dt>性别 / 床位</dt><dd>${p.sex} / ${p.bed}</dd></div><div><dt>入住日期</dt><dd>${p.admittedAt}</dd></div><div><dt>过敏记录</dt><dd>${p.allergies}</dd></div></dl><div class="history-note"><span>既往病史 / 病例摘要</span><p>${esc(p.history)}</p></div><span class="tiny muted">以上档案均为虚构</span></section></div>${historyTable(p)}<div class="mini-notice">${icon('info')}温度为 MLX90614 表面测温演示值，未转换为核心体温。AI 尚未接入，可在“原始数据与 AI”中查看预留结构。</div>`}`);}
function alerts(){const list=state.patients.filter(p=>status(p).level!=='green');return shell(`<div class="page-heading"><div><div class="eyebrow">ATTENTION & ALERTS</div><h1>关注与警报</h1><p>异常读数、跌倒事件与数据质量，集中查看。</p></div><button class="btn" data-action="refresh">${icon('refresh')}刷新</button></div><div class="notice">标记“已查看”仅保存本次演示的查看记录，不清除跌倒事件，也不改变分级。</div><div class="alert-list">${list.map(p=>{const t=status(p);return `<article class="panel alert-row"><span class="round-icon ${t.level}">${icon(STATUS[t.level].icon)}</span>${avatar(p,'mini')}<div class="alert-content"><h3><a href="#/patient/${p.id}">${p.name} <span class="muted tiny">${p.bed} 床</span></a> ${badge(t.level)}</h3><p>${esc(t.reasons.join('；'))}</p><small>最后采集 ${p.reading?clock(p.reading.measuredAt):'无'} · 模拟事件</small></div><button class="btn ${state.seen.has(p.id)?'seen':''}" data-seen="${p.id}">${icon(state.seen.has(p.id)?'check':'user')}${state.seen.has(p.id)?'本地已查看':'标记已查看'}</button><a class="btn" href="#/patient/${p.id}">详情 ${icon('chevron')}</a></article>`;}).join('')||'<div class="empty">当前没有待关注项目</div>'}</div>`,'alerts');}
function family(){const p=patient(),t=status(p);return `<div class="family-page"><header class="family-nav">${logo()}<div class="top-actions">${languageButton()}<span class="demo-pill">虚构数据</span><a class="btn small" href="#/pro">切换 Pro 模式 ${icon('chevron')}</a><a href="#/login" class="icon-btn" aria-label="退出演示">${icon('logout')}</a></div></header><main id="main" class="family-main"><div class="family-hero"><div><span class="eyebrow">BASIC · 把牵挂，放在身边</span><h1>今天，也在好好守护。</h1><p>查看家人的最新状态，让关心多一份安心。</p></div><span class="family-sun">${icon('sun')}</span></div><section class="family-person"><div class="inline">${avatar(p)}<div><h2>${p.name}<small>的健康小站</small></h2><p>${p.age} 岁 · 演示家人</p></div></div><label class="family-select">查看家人<select id="family-patient">${visibleDemoPatients().map(q=>`<option value="${q.id}" ${q.id===p.id?'selected':''}>${q.name}（虚构）</option>`).join('')}</select></label></section><section class="family-status ${t.level}"><span class="status-illustration">${icon(STATUS[t.level].icon)}</span><div><h2>${STATUS[t.level].family}</h2><p>${t.level==='green'?'目前未检测到跌倒，两项数据处于演示平稳范围。':t.level==='red'?(p.reading?.fall?.active?'设备提示可能跌倒，请查看本人情况并联系照护人员。':'有读数超出演示范围，请核实本人情况并联系照护人员。'):t.level==='yellow'?'有读数超出演示平稳范围，建议告知照护人员并核实。':'部分数据无法读取，请检查设备连接或重新采集。'}</p>${t.incomplete&&t.level!=='unknown'?'<small>同时存在数据缺失，请检查设备。</small>':''}</div></section><div class="family-metrics">${['hr','temp'].map(k=>{const m=displayMetric(p.reading,k,service.rules);return `<section class="family-metric"><span class="family-metric-icon ${k}">${icon(METRICS[k].icon)}</span><h2>${METRICS[k].name}</h2><strong class="${m.level}-text">${m.text}<small>${METRICS[k].unit}</small></strong><p>${m.level==='unknown'?m.note:m.level==='green'?'处于演示平稳范围':'需要核实一下'}</p><small>${k==='temp'?'表面测温 · 待校准':'模拟读数'}</small></section>`;}).join('')}<section class="family-metric"><span class="family-metric-icon fall">${icon('shield')}</span><h2>跌倒监测</h2><strong class="family-fall ${p.reading?.fall?.active?'red-text':''}">${p.reading?.fall?.active?'可能跌倒':isFresh(p.reading,service.rules)&&p.reading.fall.quality==='good'?'未检测到':'暂不可用'}</strong><p>${p.reading?.fall?.active?'请尽快查看本人情况':'关注日常活动状态'}</p><small>设备提示需人工核实</small></section></div><section class="family-update"><span class="round-icon mint">${icon('refresh')}</span><div><h3>最近一次数据更新</h3><p>${p.reading?clock(p.reading.measuredAt):'还没有收到数据'} · ${isFresh(p.reading,service.rules)?'模拟连接正常':'当前状态待确认'}</p></div><button class="btn" data-action="refresh">刷新状态</button></section><div class="family-note">${icon('info')}<p>这是课程演示，所有人物与读数均为虚构。页面状态仅用于展示交互，不用于判断真实健康情况。温度为表面测温演示值。</p></div><button class="btn demo-family" data-action="drawer">${icon('settings')}体验不同演示场景</button>${footnote()}</main></div>`;}
function lcd(){const p=patient();const frames=lcdFrames(p.reading,service.rules);const frame=frames[state.lcdIndex%frames.length];return shell(`<div class="page-heading"><div><div class="eyebrow">ESP32 · DEVICE DISPLAY</div><h1>小屏上的安心</h1><p>LCD 1602A 概念预览 · 16 列 × 2 行 · 英文缩写</p></div><button class="btn" data-action="drawer">${icon('settings')}切换演示场景</button></div><div class="lcd-layout"><section class="lcd-showcase"><div class="lcd-topline"><span>LCD 1602A</span><span>16 × 2 CHARACTERS</span></div><div class="lcd-board"><span class="screw s1"></span><span class="screw s2"></span><span class="screw s3"></span><span class="screw s4"></span><div class="lcd-bezel"><div class="lcd-screen" role="img" aria-label="LCD 第一行：${esc(frame[0])}；第二行：${esc(frame[1])}">${frame.map(row=>`<div class="lcd-line">${[...row].map(c=>`<span>${c===' '?'&nbsp;':esc(c)}</span>`).join('')}</div>`).join('')}</div></div><div class="lcd-pins">${'<i></i>'.repeat(16)}</div></div><div class="lcd-controls"><button class="btn" data-action="lcd-play">${icon(state.lcdAuto?'pause':'play')}${state.lcdAuto?'暂停轮播':'自动轮播'}</button><span>第 ${state.lcdIndex%frames.length+1} / ${frames.length} 页 · 每 3 秒</span><button class="btn" data-action="lcd-next">下一页 ${icon('chevron')}</button></div><div class="lcd-caption">正在预览 ${p.name}（虚构） · 与网页共享同一份演示数据</div></section><section class="panel lcd-spec"><h2>适合两行屏幕的信息层级</h2><div class="spec-item"><span>01</span><div><h3>默认轮播</h3><p>HR / SURF T 与跌倒状态页交替显示。SURF T 表示表面温度。</p></div></div><div class="spec-item"><span>02</span><div><h3>警报优先</h3><p>跌倒事件锁定警报页；严重数值异常优先显示 VALUE ALERT。人工确认机制由后端与固件接入。</p></div></div><div class="spec-item"><span>03</span><div><h3>缺失就是缺失</h3><p>无法采集时用 ---，离线或过期单独显示，避免旧数值看起来仍然有效。</p></div></div><div class="notice small-note">KY-039 原始信号不是 BPM。此处为显示逻辑概念，尚未写入 ESP32。</div><label>预览患者<select id="lcd-patient">${state.patients.map(q=>`<option value="${q.id}" ${q.id===p.id?'selected':''}>${q.name}（${q.bed}）</option>`).join('')}</select></label></section></div>`,'lcd');}
function settings(){return shell(`<div class="page-heading"><div><div class="eyebrow">CONFIGURABLE DEMO RULES</div><h1>演示规则</h1><p>调整范围，观察三种状态颜色如何变化。</p></div><span class="tag">仅本次会话生效</span></div><div class="notice">以下数值只是可编辑的课堂交互示例，没有经过医学验证。温度字段是表面测温演示值。正式接入前需由项目负责人确定规则。</div><form id="rules-form" class="panel rules-panel"><h2>数值分级</h2><p class="muted">低于 / 高于边界时触发对应分级；等于边界时进入较低一级。</p>${['hr','temp'].map(k=>`<fieldset><legend>${METRICS[k].name}（${METRICS[k].unit}）</legend><div class="rule-fields">${Object.entries(service.rules[k]).map(([field,v])=>`<label>${{severeLow:'严重低值边界',mildLow:'平稳范围下限',mildHigh:'平稳范围上限',severeHigh:'严重高值边界'}[field]}<input name="${k}.${field}" type="number" step="0.1" value="${v}" required></label>`).join('')}</div></fieldset>`).join('')}<label class="stale-field">数据失效时间（秒）<input name="staleAfterSeconds" type="number" min="5" max="300" value="${service.rules.staleAfterSeconds}" required></label><div id="rules-error" class="red-text" role="alert"></div><div class="form-actions"><button class="btn primary" type="submit">保存演示规则</button><button class="btn" type="button" data-action="reset-rules">恢复默认范围</button></div></form><div class="rules-legend"><div>${badge('red')}<p>未处理跌倒事件，或有效读数严重异常。</p></div><div>${badge('yellow')}<p>无跌倒，但有效读数轻度异常。</p></div><div>${badge('green')}<p>全部有效且新鲜，没有触发演示异常。</p></div><div>${badge('unknown')}<p>数据缺失、信号不稳、离线或过期；已知红/黄异常仍优先保留。</p></div></div>`,'settings');}
function drawer(){const p=patient();return `<div class="drawer-overlay"><section class="drawer" role="dialog" aria-modal="true" aria-labelledby="drawer-title" tabindex="-1"><div class="panel-heading"><div><span class="eyebrow">INTERACTIVE DEMO</span><h2 id="drawer-title">演示控制台</h2></div>${languageButton()}<button class="icon-btn" data-action="close-drawer" aria-label="关闭演示控制台">${icon('close')}</button></div><p class="muted">切换一位虚构患者的情况，观察医护端、家属端和小屏同步变化。</p><label>演示患者<select id="scenario-patient">${visibleDemoPatients().map(q=>`<option value="${q.id}" ${q.id===p.id?'selected':''}>${q.name} · ${q.bed}</option>`).join('')}</select></label><div class="scenario-grid">${Object.entries(SCENARIOS).map(([k,n])=>`<button data-scenario="${k}" class="scenario ${p.reading?.scenario===k?'selected':''}">${icon(k==='fall'?'fall':k==='offline'||k==='stale'?'wifi-off':k==='normal'?'shield':k==='noData'?'info':'pulse')}<span>${n}</span>${p.reading?.scenario===k?icon('check'):''}</button>`).join('')}</div><div class="notice small-note">心率不可用场景不会生成替代测量值。</div><button class="btn full" data-action="toggle-live">${icon(state.live?'pause':'play')}${state.live?'暂停模拟更新（可测试过期状态）':'恢复每 5 秒模拟更新'}</button><button class="text-btn reset-demo" data-action="reset">重置所有演示数据</button><p class="tiny muted">本控制台仅改变本页内存中的虚构数据，刷新页面恢复默认。</p></section></div>`;}
function mount(html){$('#app').innerHTML=html;localizeDom($('#app'));}
async function switchLanguage(){
 const fields=new Map([...document.querySelectorAll('form input')].map(el=>[el.name,el.value]));
 setLanguage(getLanguage()==='en'?'zh':'en');localizePageChrome();await render();
 for(const el of document.querySelectorAll('form input'))if(fields.has(el.name))el.value=fields.get(el.name);
 document.querySelector('.drawer [data-action="language"], [data-action="language"]')?.focus();
 toast(getLanguage()==='en'?'Language set to English':'已切换为中文');
}
let renderVersion=0;
async function render(){const v=++renderVersion;const r=route();if(r==='/family'&&!DEMO_SESSIONS.basic.patientIds.includes(state.selected))state.selected=DEMO_SESSIONS.basic.patientIds[0];if(r.startsWith('/patient/'))state.selected=r.split('/')[2];let content;
 try {if(r.startsWith('/patient/')){const id=state.selected;state.history=await service.getHistory(id);if(v!==renderVersion)return;content=detail(state.patients.find(p=>p.id===id));}else content=r==='/login'?login():r==='/family'?family():r==='/lcd'?lcd():r==='/settings'?settings():r==='/alerts'?alerts():dashboard();mount(content+(state.drawer?drawer():''));if(state.drawer){$('.drawer').focus();}}
 catch(e){state.error='数据加载失败，请重试。';mount(shell('<div class="empty">数据未能加载，请点击重试。</div>'));}
}
async function reload(){try{state.patients=await service.refresh();state.lastRefresh=Date.now();state.error='';await render();}catch(e){state.error='数据更新失败，已有读数可能过期。';await render();}}
function exportCSV(){const headers=['patient_id','measured_at','heart_rate_bpm','hr_quality','object_temperature_c','temp_quality','fall_active','connected','source'];const rows=state.history.map(r=>[r.patientId,r.measuredAt,r.metrics.hr.value??'',r.metrics.hr.quality,r.metrics.temp.value??'',r.metrics.temp.quality,r.fall.active,r.connected,'mock']);const csv='\ufeff'+[headers,...rows].map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`carelink-${state.selected}-mock-10min.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已导出最近十分钟模拟记录（包含质量字段）');}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.action==='language'){await switchLanguage();return;}
 if(b.dataset.role){state.role=b.dataset.role;render();}
 if(b.dataset.filter){state.filter=b.dataset.filter;if(route()!=='/pro')navigate('/pro');else render();}
 if(b.dataset.view){state.view=b.dataset.view;render();}
 if(b.dataset.tab){state.tab=b.dataset.tab;render();}
 if(b.dataset.chart){state.chart=b.dataset.chart;render();}
 if(b.dataset.seen){state.seen.add(b.dataset.seen);render();toast('已在本次演示中标记查看，警报分级仍保留');}
 if(b.dataset.scenario){service.setScenario(state.selected,b.dataset.scenario);state.patients=await service.getPatients();state.lcdIndex=0;render();toast('已切换为：'+SCENARIOS[b.dataset.scenario]);}
 switch(b.dataset.action){case 'drawer':state.previousFocus=document.activeElement;state.drawer=true;render();break;case 'close-drawer':state.drawer=false;await render();state.previousFocus?.focus();break;case 'refresh':await reload();toast('模拟数据已刷新');break;case 'clear':state.filter='all';state.query='';render();break;case 'export':exportCSV();break;case 'toggle-live':state.live=!state.live;if(state.live)await reload();else render();break;case 'reset':service.reset();state.seen.clear();state.patients=await service.getPatients();state.lcdIndex=0;render();toast('已恢复默认虚构数据');break;case 'reset-rules':service.rules=structuredClone(DEFAULT_RULES);render();toast('已恢复默认演示规则');break;case 'lcd-next':state.lcdIndex++;render();break;case 'lcd-play':state.lcdAuto=!state.lcdAuto;render();break;}
});
document.addEventListener('input',e=>{if(e.target.id==='patient-search'){state.query=e.target.value;$('#patient-results').innerHTML=patientResults();localizeDom($('#patient-results'));}});
document.addEventListener('change',e=>{if(['scenario-patient','family-patient','lcd-patient'].includes(e.target.id)){state.selected=e.target.value;state.lcdIndex=0;render();}});
document.addEventListener('submit',e=>{if(e.target.id==='login-form'){e.preventDefault();state.selected=state.role==='family'?'p004':'p001';navigate(state.role==='family'?'/family':'/pro');toast('已进入演示，未进行身份验证');}
 if(e.target.id==='rules-form'){e.preventDefault();const data=new FormData(e.target),next=structuredClone(service.rules);for(const [name,value]of data){const [k,f]=name.split('.');if(f)next[k][f]=Number(value);else next[k]=Number(value);}const valid=Object.values(next).every(v=>typeof v==='object'?Object.values(v).every(Number.isFinite):Number.isFinite(v))&&['hr','temp'].every(k=>next[k].severeLow<next[k].mildLow&&next[k].mildLow<next[k].mildHigh&&next[k].mildHigh<next[k].severeHigh)&&next.staleAfterSeconds>=5&&next.staleAfterSeconds<=300;
 if(!valid){$('#rules-error').textContent=translate('请检查边界顺序：严重低值 < 平稳下限 < 平稳上限 < 严重高值。');return;}service.rules=next;render();toast('演示规则已更新，仅本次会话有效');}
});
document.addEventListener('keydown',e=>{if(!state.drawer)return;if(e.key==='Escape'){state.drawer=false;render();}if(e.key==='Tab'){const a=[...$('.drawer').querySelectorAll('button, select, input, a[href]')];const first=a[0],last=a.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===$('.drawer'))){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();const main=$('#main');main.setAttribute('tabindex','-1');main.focus();main.scrollIntoView({block:'start'});});
window.addEventListener('hashchange',()=>{state.drawer=false;render();window.scrollTo(0,0);});
localizePageChrome();state.patients=await service.getPatients();await render();
setInterval(async()=>{if(!state.live||state.drawer||route()==='/login'||route()==='/settings'||document.activeElement?.matches('input,select'))return;await reload();},5000);
setInterval(()=>{if(route()==='/lcd'&&state.lcdAuto&&!state.drawer){state.lcdIndex++;render();}},3000);
setInterval(()=>{if(!state.live&&!state.drawer&&route()!=='/settings'&&route()!=='/login'&&!document.activeElement?.matches('input,select'))render();},5000);
